contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        uint256 beforeBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.AdjustBetAmounts(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 afterBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        assert(reverted ? afterBetLimit == beforeBetLimit : afterBetLimit == amount);
    }

    receive() external payable {}
}

